"""
Pad parallelism check (David, Oct 26, step 2a/2c). Read-only: no stepping. The pad's FLAT inner face (the triangles whose normal is within 2 degrees of the finger's own closing axis and that lie within 0.2 mm of the
innermost plane) in the world, per hand: its yaw and pitch against the closing axis, the angle between the two faces, the gap between them at the tip end and at the root end of the flat face, the fully open and
fully closed gaps, and the collision mesh against the visual mesh (the same flat face from the visual meshes).

    python experiments/pad_parallel_check.py [--out data/pad_parallel/<name>.json]
"""
import argparse, json, math, os, sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import TASK_CFG  # noqa: E402

SIDE = TASK_CFG["arm"]


def flat_face(model, data, body, geoms, toward, tol_deg=2.0, depth=0.0002):
    """Flat inner face triangles (world) of the given geoms: normal within tol_deg of +/-toward, within depth of the innermost plane."""
    tris = []
    for g in geoms:
        mid = int(model.geom_dataid[g])
        V = model.mesh_vert[model.mesh_vertadr[mid]:model.mesh_vertadr[mid] + model.mesh_vertnum[mid]].astype(float)
        F = model.mesh_face[model.mesh_faceadr[mid]:model.mesh_faceadr[mid] + model.mesh_facenum[mid]]
        Vw = V @ data.geom_xmat[g].reshape(3, 3).T + data.geom_xpos[g]
        tris.append(Vw[F])
    T = np.vstack(tris)
    n = np.cross(T[:, 1] - T[:, 0], T[:, 2] - T[:, 0])
    area = np.linalg.norm(n, axis=1) / 2
    n = n / np.maximum(np.linalg.norm(n, axis=1, keepdims=True), 1e-12)
    cen = T.mean(axis=1)
    toward = toward / np.linalg.norm(toward)
    for s in (1, -1):                                                # the winding may point either way
        facing = (n @ toward) * s
        ok = (facing > math.cos(math.radians(tol_deg))) & (area > 1e-7)
        if ok.any():
            # inner plane = the extreme centroid along "toward" among these
            ext = (cen[ok] @ toward).max()
            sel = ok & ((cen @ toward) >= ext - depth)
            if sel.sum() >= 3:
                return T[sel], area[sel]
    raise RuntimeError("no flat face")


def fit(T, area, closing, approach, vertical):
    P = T.reshape(-1, 3)
    c = P.mean(axis=0)
    # plane normal from the area-weighted triangle normals
    n = np.cross(T[:, 1] - T[:, 0], T[:, 2] - T[:, 0])
    n = n / np.linalg.norm(n, axis=1, keepdims=True)
    n = n * np.sign(n @ closing)[:, None]
    N = (n * area[:, None]).sum(axis=0); N /= np.linalg.norm(N)
    yaw = math.degrees(math.atan2(float(N @ approach), float(N @ closing)))       # about the vertical-ish axis (pad face toed toward the tips)
    pitch = math.degrees(math.atan2(float(N @ vertical), float(N @ closing)))
    a = P @ approach
    return dict(normal=N, yaw=yaw, pitch=pitch, a_min=float(a.min()), a_max=float(a.max()), w_min=float((P @ vertical).min()), w_max=float((P @ vertical).max()), centroid=c, n_tri=len(T), area=float(area.sum()))


def main():
    ap = argparse.ArgumentParser(); ap.add_argument("--out", default=None); ap.add_argument("--open", type=float, default=0.044)
    args = ap.parse_args()
    sim = load_task(TASK_CFG, cameras=False)
    model, data = sim.model, sim.data
    out = {}
    for label, q in (("closed", 0.0), ("open", args.open)):
        for j in (f"openarm_{SIDE}_finger_joint1", f"openarm_{SIDE}_finger_joint2"):
            data.qpos[model.joint(j).qposadr[0]] = q
        mujoco.mj_forward(model, data)
        hand = model.body(f"openarm_{SIDE}_hand").id
        R = data.xmat[hand].reshape(3, 3)
        approach = R[:, 2]                                             # the fingers' long axis (body z)
        j1 = model.joint(f"openarm_{SIDE}_finger_joint1")
        closing = R[:, 1]                                              # the slide joints' axis (body y), from the left finger (joint2, +y side) toward the right finger
        vertical = R[:, 0]
        res = {}
        for name in ("left_finger", "right_finger"):
            b = model.body(f"openarm_{SIDE}_{name}").id
            col = [g for g in range(model.ngeom) if int(model.geom_bodyid[g]) == b and (model.geom_contype[g] or model.geom_conaffinity[g])]
            vis = [g for g in range(model.ngeom) if int(model.geom_bodyid[g]) == b and not (model.geom_contype[g] or model.geom_conaffinity[g])]
            other = "right_finger" if name == "left_finger" else "left_finger"
            ob = model.body(f"openarm_{SIDE}_{other}").id
            toward = data.xpos[ob] - data.xpos[b]
            toward = closing * np.sign(toward @ closing)
            Tc, Ac = flat_face(model, data, b, col, toward)
            res[name] = {"collision": fit(Tc, Ac, toward, approach, vertical)}
            res[name]["toward"] = toward
            try:
                # visual: the flat face from each visual geom (tolerance a little wider; the visual mesh is finer)
                Tv, Av = flat_face(model, data, b, vis, toward, tol_deg=2.0, depth=0.0003)
                res[name]["visual"] = fit(Tv, Av, toward, approach, vertical)
            except Exception as e:
                res[name]["visual"] = {"error": str(e)}
        # angle between the two collision faces (0 = parallel) and the gaps at the tip end and root end of the flat face
        Nl, Nr = res["left_finger"]["collision"]["normal"], res["right_finger"]["collision"]["normal"]
        between = math.degrees(math.acos(float(np.clip(-(Nl @ Nr) * np.sign(-(Nl @ Nr)), -1, 1)))) if False else math.degrees(math.acos(float(np.clip(abs(Nl @ Nr), -1, 1))))
        def gap_at(a_pos):
            cl, cr = res["left_finger"]["collision"], res["right_finger"]["collision"]
            def plane_y(c):
                # position of the face plane along "closing" at approach coordinate a_pos (at the face's mean vertical position)
                N = c["normal"]; p0 = c["centroid"]
                # solve N . (p - p0) = 0 with p = p0 + da*approach + t*closing -> t = -(N.approach)/(N.closing)*da
                da = a_pos - float(p0 @ approach)
                return float(p0 @ closing) + (-(N @ approach) / (N @ closing)) * da
            return abs(plane_y(cl) - plane_y(cr))
        cl = res["left_finger"]["collision"]; cr = res["right_finger"]["collision"]
        a_lo, a_hi = max(cl["a_min"], cr["a_min"]), min(cl["a_max"], cr["a_max"])
        tip_is_hi = True
        out[label] = {"finger_pos": q, "yaw_left": cl["yaw"], "yaw_right": cr["yaw"], "pitch_left": cl["pitch"], "pitch_right": cr["pitch"], "between_deg": between,
                      "gap_a_lo_mm": gap_at(a_lo) * 1e3, "gap_a_hi_mm": gap_at(a_hi) * 1e3, "a_lo": a_lo, "a_hi": a_hi,
                      "face_size_approach_mm": (cl["a_max"] - cl["a_min"]) * 1e3, "face_size_vertical_mm": (cl["w_max"] - cl["w_min"]) * 1e3,
                      "visual_yaw_left": res["left_finger"]["visual"].get("yaw"), "visual_yaw_right": res["right_finger"]["visual"].get("yaw"),
                      "visual_gap_mm": None}
        print(label, {k: (round(v, 4) if isinstance(v, float) else v) for k, v in out[label].items()})
    if args.out:
        Path(args.out).parent.mkdir(parents=True, exist_ok=True)
        json.dump(out, open(args.out, "w"), indent=1, default=float)


if __name__ == "__main__":
    main()
